using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace SoloKnight
{
    /// <summary>
    /// All in-game UI: HUD (HP/EXP/gold/potions/cooldowns/mission), floating damage numbers, toasts,
    /// boss bar, character panel (stat allocation + equipment + inventory), pause, victory and defeat modals.
    /// The hierarchy is generated by BuildUI() (called by the editor scene builder, or at runtime as a fallback).
    /// </summary>
    [DefaultExecutionOrder(-50)]
    public class UIManager : MonoBehaviour
    {
        public static UIManager Instance { get; private set; }

        static readonly string[] StatNames = { "Attack", "Defense", "Crit Chance", "Move Speed", "Health" };
        const int InventorySlots = 20;

        // ---------- HUD ----------
        [SerializeField] RectTransform hudRoot;
        [SerializeField] Text levelText;
        [SerializeField] RectTransform hpFill;
        [SerializeField] Text hpText;
        [SerializeField] RectTransform expFill;
        [SerializeField] Text expText;
        [SerializeField] Text goldText;
        [SerializeField] Text potionText;
        [SerializeField] Text statPointsHint;
        [SerializeField] Text missionText;
        [SerializeField] Text missionProgressText;
        [SerializeField] RectTransform missionFill;
        [SerializeField] Text missionRewardText;
        [SerializeField] RectTransform dashCooldownFill;
        [SerializeField] Text dashCooldownText;
        [SerializeField] RectTransform specialCooldownFill;
        [SerializeField] Text specialCooldownText;
        [SerializeField] Text interactPromptText;
        [SerializeField] CanvasGroup floorTitleGroup;
        [SerializeField] Text floorTitleText;
        [SerializeField] Text floorSubtitleText;
        [SerializeField] CanvasGroup levelUpGroup;
        [SerializeField] Text levelUpSubText;
        [SerializeField] RectTransform floatingRoot;
        [SerializeField] RectTransform toastRoot;

        // ---------- Boss ----------
        [SerializeField] GameObject bossBarRoot;
        [SerializeField] Text bossNameText;
        [SerializeField] RectTransform bossFill;
        [SerializeField] Text bossHpText;

        // ---------- Character panel ----------
        [SerializeField] GameObject characterPanel;
        [SerializeField] Text levelInfoText;
        [SerializeField] Text statPointsText;
        [SerializeField] Text[] statValueTexts;
        [SerializeField] Button[] statPlusButtons;
        [SerializeField] Text derivedStatsText;
        [SerializeField] Button weaponSlotButton;
        [SerializeField] Text weaponSlotText;
        [SerializeField] Button armorSlotButton;
        [SerializeField] Text armorSlotText;
        [SerializeField] Text inventoryTitleText;
        [SerializeField] Button[] inventorySlotButtons;
        [SerializeField] Text[] inventorySlotTexts;
        [SerializeField] Image[] inventorySlotImages;
        [SerializeField] Text itemDetailText;
        [SerializeField] Button equipButton;
        [SerializeField] Button salvageButton;
        [SerializeField] Text salvageButtonText;
        [SerializeField] Button closeCharacterButton;

        // ---------- Modals ----------
        [SerializeField] GameObject pausePanel;
        [SerializeField] Button resumeButton;
        [SerializeField] Button saveButton;
        [SerializeField] Button pauseMenuButton;
        [SerializeField] Button pauseQuitButton;
        [SerializeField] GameObject defeatPanel;
        [SerializeField] Text defeatInfoText;
        [SerializeField] Button retryButton;
        [SerializeField] Button defeatMenuButton;
        [SerializeField] GameObject victoryPanel;
        [SerializeField] Text victoryTitleText;
        [SerializeField] Text victoryInfoText;
        [SerializeField] Button nextFloorButton;
        [SerializeField] Button keepExploringButton;

        class FloatingEntry { public Text text; public Vector3 world; public float age; public float life; public Vector3 drift; public float baseScale; }
        class ToastEntry { public Text text; public float age; }

        readonly List<FloatingEntry> floating = new List<FloatingEntry>();
        readonly Stack<Text> floatingPool = new Stack<Text>();
        readonly List<ToastEntry> toasts = new List<ToastEntry>();
        EnemyStats trackedBoss;
        float floorTitleTimer;
        float levelUpTimer;
        int selectedItemIndex = -1;
        float panelRefreshTimer;

        public bool IsBlockingPanelOpen => characterPanel != null && characterPanel.activeSelf;

        // =====================================================================
        // Lifecycle
        // =====================================================================

        void Awake()
        {
            Instance = this;
            if (hudRoot == null) BuildUI();
            UIFactory.EnsureEventSystem();
            WireButtons();
            characterPanel.SetActive(false);
            pausePanel.SetActive(false);
            defeatPanel.SetActive(false);
            victoryPanel.SetActive(false);
            bossBarRoot.SetActive(false);
            floorTitleGroup.alpha = 0f;
            levelUpGroup.alpha = 0f;
            interactPromptText.text = "";
        }

        void OnDestroy()
        {
            if (Instance == this) Instance = null;
        }

        void WireButtons()
        {
            for (int i = 0; i < statPlusButtons.Length; i++)
            {
                int idx = i;
                statPlusButtons[i].onClick.AddListener(() => AllocateStat((StatType)idx));
            }
            for (int i = 0; i < inventorySlotButtons.Length; i++)
            {
                int idx = i;
                inventorySlotButtons[i].onClick.AddListener(() => SelectItem(idx));
            }
            weaponSlotButton.onClick.AddListener(() => UnequipSlot(ItemType.Weapon));
            armorSlotButton.onClick.AddListener(() => UnequipSlot(ItemType.Armor));
            equipButton.onClick.AddListener(EquipSelected);
            salvageButton.onClick.AddListener(SalvageSelected);
            closeCharacterButton.onClick.AddListener(() => SetCharacterPanel(false));

            resumeButton.onClick.AddListener(() => SetPause(false));
            saveButton.onClick.AddListener(() =>
            {
                if (GameManager.Instance != null) GameManager.Instance.SaveGame();
                Click();
                Toast("Game saved.", new Color(0.6f, 1f, 0.6f));
            });
            pauseMenuButton.onClick.AddListener(() => { Click(); if (GameManager.Instance != null) GameManager.Instance.ReturnToMenu(); });
            pauseQuitButton.onClick.AddListener(() => { Click(); if (GameManager.Instance != null) GameManager.Instance.QuitGame(); });

            retryButton.onClick.AddListener(() => { Click(); if (GameManager.Instance != null) GameManager.Instance.RetryFloor(); });
            defeatMenuButton.onClick.AddListener(() => { Click(); if (GameManager.Instance != null) GameManager.Instance.ReturnToMenu(); });

            nextFloorButton.onClick.AddListener(() => { Click(); if (GameManager.Instance != null) GameManager.Instance.AdvanceFloor(); });
            keepExploringButton.onClick.AddListener(() =>
            {
                Click();
                victoryPanel.SetActive(false);
                if (GameManager.Instance != null) GameManager.Instance.ResumeAfterVictory();
                Toast("The exit portal awaits in the boss room. Press F at the portal to descend.", UIFactory.AccentColor);
            });
        }

        static void Click() => AudioManager.Play(Sfx.UiClick, 1f, 0f);

        void Update()
        {
            HandleInput();
            RefreshHUD();
            UpdateFloating();
            UpdateToasts();
            UpdateBanners();

            if (characterPanel.activeSelf)
            {
                panelRefreshTimer -= Time.unscaledDeltaTime;
                if (panelRefreshTimer <= 0f) { panelRefreshTimer = 0.25f; RefreshCharacterPanel(); }
            }
        }

        void HandleInput()
        {
            var gm = GameManager.Instance;
            GameState state = gm != null ? gm.State : GameState.Playing;

            if (Input.GetKeyDown(KeyCode.Tab) || Input.GetKeyDown(KeyCode.I))
            {
                if (characterPanel.activeSelf) SetCharacterPanel(false);
                else if (state == GameState.Playing) SetCharacterPanel(true);
            }

            if (Input.GetKeyDown(KeyCode.Escape))
            {
                if (characterPanel.activeSelf) SetCharacterPanel(false);
                else if (state == GameState.Paused) SetPause(false);
                else if (state == GameState.Playing) SetPause(true);
            }
        }

        // =====================================================================
        // HUD
        // =====================================================================

        void RefreshHUD()
        {
            var pc = PlayerController.Instance;
            if (pc == null || pc.Stats == null) return;
            var s = pc.Stats;
            var inv = pc.Inventory;

            levelText.text = $"Lv {s.Level}";
            UIFactory.SetFill(hpFill, s.MaxHP > 0 ? s.CurrentHP / (float)s.MaxHP : 0f);
            hpText.text = $"{s.CurrentHP} / {s.MaxHP}";
            UIFactory.SetFill(expFill, s.Exp / (float)Mathf.Max(1, s.ExpToNextLevel));
            expText.text = $"EXP {s.Exp} / {s.ExpToNextLevel}";
            goldText.text = $"<color=#FFD54A>Gold</color>  {inv.Gold}";

            var p1 = inv.GetPotionItem(0);
            var p2 = inv.GetPotionItem(1);
            potionText.text = $"<color=#FF7A7A>[1]</color> {(p1 ? p1.displayName : "Potion")} x{inv.GetPotionCount(0)}    <color=#FF7A7A>[2]</color> {(p2 ? p2.displayName : "Greater")} x{inv.GetPotionCount(1)}";
            statPointsHint.text = s.StatPoints > 0 ? $"+{s.StatPoints} stat point{(s.StatPoints == 1 ? "" : "s")}!  Press [Tab]" : "";

            UIFactory.SetFill(dashCooldownFill, pc.DashCooldownNormalized);
            dashCooldownText.text = pc.DashCooldownRemaining > 0.05f ? pc.DashCooldownRemaining.ToString("0.0") : "";
            UIFactory.SetFill(specialCooldownFill, pc.Combat.SpecialCooldownNormalized);
            specialCooldownText.text = pc.Combat.SpecialCooldownRemaining > 0.05f ? pc.Combat.SpecialCooldownRemaining.ToString("0.0") : "";

            var mm = MissionManager.Instance;
            if (mm != null && mm.IsActive)
            {
                missionText.text = mm.IsCompleted ? $"<color=#7CFF8A>[DONE] {mm.Description}</color>" : mm.Description;
                missionProgressText.text = $"{mm.Progress} / {mm.Target}";
                UIFactory.SetFill(missionFill, mm.Target > 0 ? mm.Progress / (float)mm.Target : 0f);
                missionRewardText.text = mm.IsCompleted ? "Reward claimed" : $"Reward: {mm.RewardExp} EXP, {mm.RewardGold} Gold";
            }

            if (trackedBoss != null && bossBarRoot.activeSelf)
            {
                UIFactory.SetFill(bossFill, trackedBoss.CurrentHP / (float)Mathf.Max(1, trackedBoss.maxHP));
                bossHpText.text = $"{trackedBoss.CurrentHP} / {trackedBoss.maxHP}";
                var ai = trackedBoss.GetComponent<BossAI>();
                bossNameText.text = ai != null && ai.IsEnraged ? $"<color=#FF5A4A>{trackedBoss.enemyName}  (ENRAGED)</color>" : trackedBoss.enemyName;
            }
        }

        public void SetInteractPrompt(string prompt)
        {
            if (interactPromptText != null) interactPromptText.text = prompt ?? "";
        }

        public void ShowFloorTitle(int floor, string floorName)
        {
            floorTitleText.text = $"FLOOR {floor}";
            floorSubtitleText.text = floorName;
            floorTitleTimer = 3.5f;
        }

        public void ShowLevelUp(int level, int points)
        {
            levelUpSubText.text = $"Level {level}  ·  {points} stat point{(points == 1 ? "" : "s")} available  [Tab]";
            levelUpTimer = 2.5f;
            Toast($"<color=#FFD54A>Level Up!</color> You reached level {level}.", Color.white);
        }

        void UpdateBanners()
        {
            float dt = Time.unscaledDeltaTime;
            if (floorTitleTimer > 0f)
            {
                floorTitleTimer -= dt;
                floorTitleGroup.alpha = Mathf.Clamp01(Mathf.Min(floorTitleTimer, 3.5f - floorTitleTimer) * 2f);
            }
            else floorTitleGroup.alpha = 0f;

            if (levelUpTimer > 0f)
            {
                levelUpTimer -= dt;
                levelUpGroup.alpha = Mathf.Clamp01(levelUpTimer * 2f);
                float pop = 1f + Mathf.Max(0f, levelUpTimer - 2.2f) * 1.5f;
                levelUpGroup.transform.localScale = Vector3.one * pop;
            }
            else levelUpGroup.alpha = 0f;
        }

        public void ShowBossBar(EnemyStats boss)
        {
            trackedBoss = boss;
            bossBarRoot.SetActive(true);
            bossNameText.text = boss.enemyName;
        }

        public void HideBossBar()
        {
            bossBarRoot.SetActive(false);
            trackedBoss = null;
        }

        // =====================================================================
        // Floating text / damage numbers / toasts
        // =====================================================================

        public static void DamageNumber(Vector3 world, int amount, Color color, bool crit)
        {
            if (Instance == null) return;
            Instance.SpawnFloating(world, crit ? $"{amount}!" : amount.ToString(), color, crit ? 40 : 28, crit ? 1.35f : 1f);
        }

        public static void FloatingText(Vector3 world, string text, Color color, int size)
        {
            if (Instance == null) return;
            Instance.SpawnFloating(world, text, color, size, 1f);
        }

        public static void Toast(string message, Color color)
        {
            if (Instance == null) return;
            Instance.AddToast(message, color);
        }

        void SpawnFloating(Vector3 world, string text, Color color, int size, float scale)
        {
            Text t = floatingPool.Count > 0 ? floatingPool.Pop() : UIFactory.Label("Floating", floatingRoot, "", size, TextAnchor.MiddleCenter, Color.white, FontStyle.Bold);
            t.gameObject.SetActive(true);
            t.rectTransform.sizeDelta = new Vector2(260f, 60f);
            t.text = text;
            t.fontSize = size;
            t.color = color;
            floating.Add(new FloatingEntry
            {
                text = t,
                world = world + new Vector3(Random.Range(-0.3f, 0.3f), 0f, Random.Range(-0.2f, 0.2f)),
                life = 0.9f,
                drift = new Vector3(Random.Range(-0.4f, 0.4f), 1.6f, 0f),
                baseScale = scale
            });
        }

        void UpdateFloating()
        {
            var cam = Camera.main;
            float dt = Time.unscaledDeltaTime;
            for (int i = floating.Count - 1; i >= 0; i--)
            {
                var f = floating[i];
                f.age += dt;
                if (f.age >= f.life || cam == null)
                {
                    f.text.gameObject.SetActive(false);
                    floatingPool.Push(f.text);
                    floating.RemoveAt(i);
                    continue;
                }
                float k = f.age / f.life;
                Vector3 wp = f.world + f.drift * k;
                Vector3 sp = cam.WorldToScreenPoint(wp);
                if (sp.z < 0f) { f.text.enabled = false; continue; }
                f.text.enabled = true;
                RectTransformUtility.ScreenPointToLocalPointInRectangle(floatingRoot, sp, null, out Vector2 local);
                f.text.rectTransform.anchoredPosition = local;
                float pop = k < 0.15f ? Mathf.Lerp(1.6f, 1f, k / 0.15f) : 1f;
                f.text.rectTransform.localScale = Vector3.one * f.baseScale * pop;
                var c = f.text.color;
                c.a = k > 0.6f ? 1f - (k - 0.6f) / 0.4f : 1f;
                f.text.color = c;
            }
        }

        void AddToast(string message, Color color)
        {
            var t = UIFactory.Label("Toast", toastRoot, message, 22, TextAnchor.LowerLeft, color);
            t.rectTransform.anchorMin = t.rectTransform.anchorMax = new Vector2(0f, 0f);
            t.rectTransform.pivot = new Vector2(0f, 0f);
            t.rectTransform.sizeDelta = new Vector2(760f, 30f);
            toasts.Add(new ToastEntry { text = t });
            while (toasts.Count > 6)
            {
                Destroy(toasts[0].text.gameObject);
                toasts.RemoveAt(0);
            }
        }

        void UpdateToasts()
        {
            float dt = Time.unscaledDeltaTime;
            for (int i = toasts.Count - 1; i >= 0; i--)
            {
                var e = toasts[i];
                e.age += dt;
                if (e.age > 4.5f)
                {
                    Destroy(e.text.gameObject);
                    toasts.RemoveAt(i);
                }
            }
            for (int i = 0; i < toasts.Count; i++)
            {
                var e = toasts[i];
                int fromBottom = toasts.Count - 1 - i;
                e.text.rectTransform.anchoredPosition = new Vector2(0f, fromBottom * 32f);
                var c = e.text.color;
                c.a = e.age > 3.8f ? Mathf.Clamp01(1f - (e.age - 3.8f) / 0.7f) : 1f;
                e.text.color = c;
            }
        }

        // =====================================================================
        // Character panel
        // =====================================================================

        public void SetCharacterPanel(bool open)
        {
            var gm = GameManager.Instance;
            if (open && gm != null && gm.State != GameState.Playing) return;
            if (characterPanel.activeSelf == open) return;
            characterPanel.SetActive(open);
            Click();
            if (open)
            {
                selectedItemIndex = -1;
                RefreshCharacterPanel();
                Time.timeScale = 0f;
            }
            else if (gm == null || gm.State == GameState.Playing)
            {
                Time.timeScale = 1f;
            }
        }

        void AllocateStat(StatType stat)
        {
            var pc = PlayerController.Instance;
            if (pc != null && pc.Stats.AllocateStat(stat)) RefreshCharacterPanel();
        }

        void SelectItem(int index)
        {
            var pc = PlayerController.Instance;
            if (pc == null || index >= pc.Inventory.Items.Count) return;
            selectedItemIndex = selectedItemIndex == index ? -1 : index;
            Click();
            RefreshCharacterPanel();
        }

        void EquipSelected()
        {
            var pc = PlayerController.Instance;
            if (pc == null || selectedItemIndex < 0) return;
            pc.Inventory.EquipFromInventory(selectedItemIndex);
            selectedItemIndex = -1;
            RefreshCharacterPanel();
        }

        void SalvageSelected()
        {
            var pc = PlayerController.Instance;
            if (pc == null || selectedItemIndex < 0) return;
            var item = pc.Inventory.Items[selectedItemIndex];
            int gold = pc.Inventory.Salvage(selectedItemIndex);
            Toast($"Salvaged {item.RichName} for {gold} gold.", new Color(1f, 0.85f, 0.4f));
            selectedItemIndex = -1;
            RefreshCharacterPanel();
        }

        void UnequipSlot(ItemType slot)
        {
            var pc = PlayerController.Instance;
            if (pc == null) return;
            if (pc.Inventory.Unequip(slot)) Click();
            RefreshCharacterPanel();
        }

        static string ColorHex(Color c) => ColorUtility.ToHtmlStringRGB(c);

        void RefreshCharacterPanel()
        {
            var pc = PlayerController.Instance;
            if (pc == null) return;
            var s = pc.Stats;
            var inv = pc.Inventory;

            levelInfoText.text = $"Level <b>{s.Level}</b>     EXP {s.Exp} / {s.ExpToNextLevel}";
            statPointsText.text = s.StatPoints > 0
                ? $"<color=#FFD54A>{s.StatPoints} stat point{(s.StatPoints == 1 ? "" : "s")} to spend</color>"
                : "<color=#888888>No stat points - level up to earn more</color>";

            statValueTexts[(int)StatType.Attack].text = $"{s.Attack}   <size=16><color=#999999>(+{s.attackPerPoint}/pt)</color></size>";
            statValueTexts[(int)StatType.Defense].text = $"{s.Defense}   <size=16><color=#999999>(-{Mathf.RoundToInt(s.DamageReductionPercent * 100f)}% dmg)</color></size>";
            statValueTexts[(int)StatType.CritChance].text = $"{Mathf.RoundToInt(s.CritChance * 100f)}%   <size=16><color=#999999>(x{PlayerStats.CritMultiplier} dmg, max {Mathf.RoundToInt(PlayerStats.CritCap * 100f)}%)</color></size>";
            statValueTexts[(int)StatType.MoveSpeed].text = $"{s.MoveSpeed:0.00}   <size=16><color=#999999>(+{s.moveSpeedPerPoint}/pt)</color></size>";
            statValueTexts[(int)StatType.Health].text = $"{s.CurrentHP}/{s.MaxHP}   <size=16><color=#999999>(+{s.maxHPPerPoint}/pt, heals)</color></size>";
            bool canSpend = s.StatPoints > 0 && !(s.CritChance >= PlayerStats.CritCap);
            for (int i = 0; i < statPlusButtons.Length; i++)
            {
                bool ok = s.StatPoints > 0 && !(i == (int)StatType.CritChance && !canSpend);
                statPlusButtons[i].interactable = ok;
            }

            derivedStatsText.text =
                $"Allocated:  ATK {s.GetAllocated(StatType.Attack)}  ·  DEF {s.GetAllocated(StatType.Defense)}  ·  CRIT {s.GetAllocated(StatType.CritChance)}  ·  SPD {s.GetAllocated(StatType.MoveSpeed)}  ·  HP {s.GetAllocated(StatType.Health)}\n" +
                $"Gear bonus:  ATK +{inv.BonusAttack}  ·  DEF +{inv.BonusDefense}  ·  CRIT +{Mathf.RoundToInt(inv.BonusCritChance * 100f)}%  ·  SPD +{inv.BonusMoveSpeed:0.##}  ·  HP +{inv.BonusMaxHP}\n" +
                $"Gold: <color=#FFD54A>{inv.Gold}</color>     Floor {(GameManager.Instance != null ? GameManager.Instance.Data.currentFloor : 1)}";

            weaponSlotText.text = inv.EquippedWeapon != null ? $"{inv.EquippedWeapon.RichName}\n<size=14><color=#999999>Weapon - click to unequip</color></size>" : "<color=#777777>No Weapon</color>";
            armorSlotText.text = inv.EquippedArmor != null ? $"{inv.EquippedArmor.RichName}\n<size=14><color=#999999>Armor - click to unequip</color></size>" : "<color=#777777>No Armor</color>";

            inventoryTitleText.text = $"INVENTORY  ({inv.Items.Count}/{inv.capacity})";
            for (int i = 0; i < inventorySlotButtons.Length; i++)
            {
                bool has = i < inv.Items.Count;
                var item = has ? inv.Items[i] : null;
                inventorySlotButtons[i].interactable = has;
                inventorySlotTexts[i].text = has ? $"<color=#{ColorHex(item.DisplayColor)}>{item.displayName}</color>" : "";
                Color baseCol = has ? Color.Lerp(UIFactory.ButtonColor, item.DisplayColor, 0.25f) : new Color(0.13f, 0.13f, 0.16f);
                if (i == selectedItemIndex) baseCol = Color.Lerp(baseCol, UIFactory.AccentColor, 0.45f);
                inventorySlotImages[i].color = baseCol;
            }

            if (selectedItemIndex >= 0 && selectedItemIndex < inv.Items.Count)
            {
                var item = inv.Items[selectedItemIndex];
                var equipped = item.itemType == ItemType.Weapon ? inv.EquippedWeapon : inv.EquippedArmor;
                string compare = equipped != null ? $"\n<color=#999999>Equipped: {equipped.displayName} ({equipped.GetStatSummary().Replace("\n", ", ")})</color>" : "";
                itemDetailText.text = $"<b>{item.RichName}</b>  <color=#999999>{item.rarity} {item.itemType}</color>\n{item.GetStatSummary().Replace("\n", ",  ")}{compare}";
                equipButton.interactable = item.IsEquipment;
                salvageButton.interactable = true;
                salvageButtonText.text = $"Salvage (+{item.sellValue}g)";
            }
            else
            {
                itemDetailText.text = "<color=#888888>Select an item to inspect, equip or salvage it.\nClick an equipped slot to unequip.</color>";
                equipButton.interactable = false;
                salvageButton.interactable = false;
                salvageButtonText.text = "Salvage";
            }
        }

        // =====================================================================
        // Pause / Victory / Defeat
        // =====================================================================

        void SetPause(bool paused)
        {
            var gm = GameManager.Instance;
            if (gm == null) return;
            gm.SetPaused(paused);
            pausePanel.SetActive(gm.State == GameState.Paused);
            Click();
        }

        public void ShowDefeat()
        {
            SetCharacterPanel(false);
            HideBossBar();
            StartCoroutine(ShowDelayed(defeatPanel, 1.3f, () =>
            {
                var gm = GameManager.Instance;
                int lvl = gm != null ? gm.Data.level : 1;
                int floor = gm != null ? gm.Data.currentFloor : 1;
                defeatInfoText.text = $"You fell on Floor {floor}.\nYour level ({lvl}), stats, gold and gear are kept.";
            }));
        }

        public void ShowVictory(int floor, string floorName, string bossName)
        {
            SetCharacterPanel(false);
            StartCoroutine(ShowDelayed(victoryPanel, 1.8f, () =>
            {
                victoryTitleText.text = $"FLOOR {floor} CLEARED!";
                victoryInfoText.text = $"{bossName} of the {floorName} has been defeated.\nThe exit portal has opened. Progress saved.";
            }));
        }

        IEnumerator ShowDelayed(GameObject panel, float delay, System.Action setup)
        {
            yield return new WaitForSecondsRealtime(delay);
            setup?.Invoke();
            pausePanel.SetActive(false);
            panel.SetActive(true);
            Time.timeScale = 0f;
        }

        // =====================================================================
        // Builder
        // =====================================================================

        /// <summary>Generates the full UI hierarchy under this Canvas and assigns every reference.</summary>
        public void BuildUI()
        {
            UIFactory.ConfigureCanvas(gameObject, 10);
            UIFactory.ClearChildren(transform);
            Color dim = new Color(0.65f, 0.65f, 0.7f);

            // ---------------- HUD root ----------------
            hudRoot = UIFactory.Stretch(UIFactory.Rect("HUD", transform));

            floatingRoot = UIFactory.Stretch(UIFactory.Rect("FloatingText", hudRoot));

            // Player panel (top-left)
            var player = UIFactory.Panel("PlayerPanel", hudRoot, UIFactory.PanelColor, false).rectTransform;
            UIFactory.Place(player, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(20f, -20f), new Vector2(460f, 176f));
            levelText = UIFactory.Label("Level", player, "Lv 1", 30, TextAnchor.MiddleLeft, UIFactory.AccentColor, FontStyle.Bold);
            UIFactory.PlaceTL(levelText.rectTransform, 16f, 8f, 120f, 40f);
            UIFactory.PlaceTL(UIFactory.Label("Name", player, "SOLO KNIGHT", 16, TextAnchor.MiddleLeft, dim).rectTransform, 120f, 14f, 300f, 30f);
            var hpBar = UIFactory.Bar("HPBar", player, new Color(0.15f, 0.04f, 0.04f), new Color(0.85f, 0.18f, 0.2f), out hpFill);
            UIFactory.PlaceTL(hpBar, 16f, 52f, 428f, 30f);
            hpText = UIFactory.Label("HPText", hpBar, "100 / 100", 18, TextAnchor.MiddleCenter, Color.white, FontStyle.Bold);
            UIFactory.Stretch(hpText.rectTransform);
            var expBar = UIFactory.Bar("EXPBar", player, new Color(0.05f, 0.08f, 0.15f), new Color(0.35f, 0.65f, 1f), out expFill);
            UIFactory.PlaceTL(expBar, 16f, 88f, 428f, 14f);
            expText = UIFactory.Label("EXPText", player, "EXP 0 / 60", 14, TextAnchor.MiddleRight, dim);
            UIFactory.PlaceTL(expText.rectTransform, 16f, 102f, 428f, 22f);
            goldText = UIFactory.Label("Gold", player, "Gold 0", 18, TextAnchor.MiddleLeft, Color.white);
            UIFactory.PlaceTL(goldText.rectTransform, 16f, 104f, 200f, 24f);
            potionText = UIFactory.Label("Potions", player, "", 16, TextAnchor.MiddleLeft, Color.white);
            UIFactory.PlaceTL(potionText.rectTransform, 16f, 136f, 440f, 26f);
            statPointsHint = UIFactory.Label("StatHint", hudRoot, "", 20, TextAnchor.MiddleLeft, UIFactory.AccentColor, FontStyle.Bold);
            UIFactory.Place(statPointsHint.rectTransform, new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(24f, -202f), new Vector2(460f, 30f));

            // Mission panel (top-right)
            var mission = UIFactory.Panel("MissionPanel", hudRoot, UIFactory.PanelColor, false).rectTransform;
            UIFactory.Place(mission, new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(-20f, -20f), new Vector2(400f, 138f));
            UIFactory.PlaceTL(UIFactory.Label("Header", mission, "FLOOR MISSION", 15, TextAnchor.MiddleLeft, UIFactory.AccentColor, FontStyle.Bold).rectTransform, 16f, 8f, 360f, 24f);
            missionText = UIFactory.Label("Mission", mission, "-", 22, TextAnchor.MiddleLeft, Color.white, FontStyle.Bold);
            UIFactory.PlaceTL(missionText.rectTransform, 16f, 34f, 370f, 30f);
            var mBar = UIFactory.Bar("MissionBar", mission, new Color(0.08f, 0.12f, 0.08f), new Color(0.4f, 0.85f, 0.45f), out missionFill);
            UIFactory.PlaceTL(mBar, 16f, 70f, 300f, 16f);
            missionProgressText = UIFactory.Label("Progress", mission, "0 / 0", 16, TextAnchor.MiddleRight, Color.white);
            UIFactory.PlaceTL(missionProgressText.rectTransform, 300f, 66f, 84f, 24f);
            missionRewardText = UIFactory.Label("Reward", mission, "", 14, TextAnchor.MiddleLeft, dim);
            UIFactory.PlaceTL(missionRewardText.rectTransform, 16f, 98f, 370f, 26f);

            // Boss bar (top-center)
            var boss = UIFactory.Rect("BossBar", hudRoot);
            UIFactory.Place(boss, new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -24f), new Vector2(820f, 80f));
            bossBarRoot = boss.gameObject;
            bossNameText = UIFactory.Label("BossName", boss, "Boss", 26, TextAnchor.MiddleCenter, new Color(1f, 0.85f, 0.8f), FontStyle.Bold);
            UIFactory.PlaceTL(bossNameText.rectTransform, 0f, 0f, 820f, 34f);
            var bBar = UIFactory.Bar("Bar", boss, new Color(0.12f, 0.02f, 0.02f, 0.9f), new Color(0.75f, 0.1f, 0.12f), out bossFill);
            UIFactory.PlaceTL(bBar, 0f, 38f, 820f, 30f);
            bossHpText = UIFactory.Label("BossHP", bBar, "", 16, TextAnchor.MiddleCenter, Color.white, FontStyle.Bold);
            UIFactory.Stretch(bossHpText.rectTransform);

            // Ability bar (bottom-center)
            var abilities = UIFactory.Rect("Abilities", hudRoot);
            UIFactory.Place(abilities, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 24f), new Vector2(220f, 110f));
            BuildAbilitySlot(abilities, "Dash", "SPACE", 0f, new Color(0.35f, 0.6f, 0.9f), out dashCooldownFill, out dashCooldownText);
            BuildAbilitySlot(abilities, "Whirlwind", "RMB / Q", 120f, new Color(0.85f, 0.45f, 0.25f), out specialCooldownFill, out specialCooldownText);

            interactPromptText = UIFactory.Label("InteractPrompt", hudRoot, "", 26, TextAnchor.MiddleCenter, UIFactory.AccentColor, FontStyle.Bold);
            UIFactory.Place(interactPromptText.rectTransform, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), new Vector2(0f, 150f), new Vector2(800f, 40f));

            toastRoot = UIFactory.Rect("Toasts", hudRoot);
            UIFactory.Place(toastRoot, new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(24f, 24f), new Vector2(760f, 220f));

            var controls = UIFactory.Label("Controls", hudRoot,
                "WASD Move  ·  LMB Attack  ·  RMB/Q Whirlwind  ·  Space Dash  ·  F Interact  ·  1/2 Potions  ·  Tab Character  ·  Esc Pause",
                14, TextAnchor.LowerRight, new Color(0.7f, 0.7f, 0.75f, 0.8f));
            UIFactory.Place(controls.rectTransform, new Vector2(1f, 0f), new Vector2(1f, 0f), new Vector2(-20f, 12f), new Vector2(900f, 24f));

            // Floor title (center)
            var title = UIFactory.Rect("FloorTitle", hudRoot);
            UIFactory.Place(title, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0f, 220f), new Vector2(900f, 140f));
            floorTitleGroup = title.gameObject.AddComponent<CanvasGroup>();
            floorTitleGroup.blocksRaycasts = false;
            floorTitleText = UIFactory.Label("Title", title, "FLOOR 1", 64, TextAnchor.MiddleCenter, Color.white, FontStyle.Bold);
            UIFactory.PlaceTL(floorTitleText.rectTransform, 0f, 0f, 900f, 80f);
            floorSubtitleText = UIFactory.Label("Subtitle", title, "Stone Catacombs", 30, TextAnchor.MiddleCenter, UIFactory.AccentColor);
            UIFactory.PlaceTL(floorSubtitleText.rectTransform, 0f, 80f, 900f, 50f);

            // Level up banner
            var lvl = UIFactory.Rect("LevelUp", hudRoot);
            UIFactory.Place(lvl, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0f, 110f), new Vector2(900f, 120f));
            levelUpGroup = lvl.gameObject.AddComponent<CanvasGroup>();
            levelUpGroup.blocksRaycasts = false;
            UIFactory.PlaceTL(UIFactory.Label("Text", lvl, "LEVEL UP!", 58, TextAnchor.MiddleCenter, UIFactory.AccentColor, FontStyle.Bold).rectTransform, 0f, 0f, 900f, 72f);
            levelUpSubText = UIFactory.Label("Sub", lvl, "", 24, TextAnchor.MiddleCenter, Color.white);
            UIFactory.PlaceTL(levelUpSubText.rectTransform, 0f, 72f, 900f, 40f);

            BuildCharacterPanel(dim);
            BuildModals();
        }

        void BuildAbilitySlot(RectTransform parent, string name, string key, float x, Color color, out RectTransform cooldownFill, out Text cooldownText)
        {
            var slot = UIFactory.Panel(name, parent, new Color(color.r * 0.35f, color.g * 0.35f, color.b * 0.35f, 0.95f), false).rectTransform;
            UIFactory.PlaceTL(slot, x, 0f, 100f, 80f);
            UIFactory.Stretch(UIFactory.Label("Name", slot, name, 17, TextAnchor.MiddleCenter, Color.white, FontStyle.Bold).rectTransform);
            // Cooldown overlay shrinks from the left as the ability recharges.
            var overlay = UIFactory.Panel("Cooldown", slot, new Color(0f, 0f, 0f, 0.7f), false).rectTransform;
            overlay.anchorMin = Vector2.zero;
            overlay.anchorMax = new Vector2(0f, 1f);
            overlay.offsetMin = Vector2.zero;
            overlay.offsetMax = Vector2.zero;
            cooldownFill = overlay;
            cooldownText = UIFactory.Label("CD", slot, "", 26, TextAnchor.MiddleCenter, Color.white, FontStyle.Bold);
            UIFactory.Stretch(cooldownText.rectTransform);
            var keyLabel = UIFactory.Label("Key", parent, key, 14, TextAnchor.MiddleCenter, new Color(0.75f, 0.75f, 0.8f));
            UIFactory.PlaceTL(keyLabel.rectTransform, x, 82f, 100f, 22f);
        }

        void BuildCharacterPanel(Color dim)
        {
            var win = UIFactory.Modal("CharacterPanel", transform, new Vector2(1180f, 720f), out characterPanel);
            UIFactory.PlaceTL(UIFactory.Label("Title", win, "CHARACTER", 34, TextAnchor.MiddleLeft, UIFactory.AccentColor, FontStyle.Bold).rectTransform, 30f, 18f, 400f, 44f);
            UIFactory.PlaceTL(UIFactory.Label("Hint", win, "[Tab] / [Esc] to close  ·  game paused", 15, TextAnchor.MiddleRight, dim).rectTransform, 680f, 26f, 380f, 30f);
            closeCharacterButton = UIFactory.Button("Close", win, "X", 22, new Color(0.45f, 0.15f, 0.15f), out _);
            UIFactory.PlaceTL((RectTransform)closeCharacterButton.transform, 1110f, 18f, 46f, 40f);

            // ---- Stats column ----
            levelInfoText = UIFactory.Label("LevelInfo", win, "", 22, TextAnchor.MiddleLeft, Color.white);
            UIFactory.PlaceTL(levelInfoText.rectTransform, 30f, 74f, 520f, 32f);
            statPointsText = UIFactory.Label("StatPoints", win, "", 20, TextAnchor.MiddleLeft, Color.white, FontStyle.Bold);
            UIFactory.PlaceTL(statPointsText.rectTransform, 30f, 108f, 520f, 30f);

            statValueTexts = new Text[5];
            statPlusButtons = new Button[5];
            for (int i = 0; i < 5; i++)
            {
                float y = 150f + i * 62f;
                var row = UIFactory.Panel("Stat_" + StatNames[i], win, new Color(1f, 1f, 1f, 0.04f), false).rectTransform;
                UIFactory.PlaceTL(row, 30f, y, 540f, 54f);
                UIFactory.PlaceTL(UIFactory.Label("Name", row, StatNames[i], 21, TextAnchor.MiddleLeft, dim, FontStyle.Bold).rectTransform, 14f, 0f, 150f, 54f);
                statValueTexts[i] = UIFactory.Label("Value", row, "0", 22, TextAnchor.MiddleLeft, Color.white);
                UIFactory.PlaceTL(statValueTexts[i].rectTransform, 160f, 0f, 320f, 54f);
                statPlusButtons[i] = UIFactory.Button("Plus", row, "+", 28, new Color(0.25f, 0.45f, 0.25f), out _);
                UIFactory.PlaceTL((RectTransform)statPlusButtons[i].transform, 486f, 6f, 46f, 42f);
            }
            derivedStatsText = UIFactory.Label("Derived", win, "", 15, TextAnchor.UpperLeft, dim);
            UIFactory.PlaceTL(derivedStatsText.rectTransform, 30f, 470f, 540f, 90f);

            // ---- Equipment + inventory column ----
            float rx = 600f;
            UIFactory.PlaceTL(UIFactory.Label("EquipHeader", win, "EQUIPMENT", 18, TextAnchor.MiddleLeft, UIFactory.AccentColor, FontStyle.Bold).rectTransform, rx, 74f, 300f, 30f);
            weaponSlotButton = UIFactory.Button("WeaponSlot", win, "", 18, UIFactory.ButtonColor, out weaponSlotText);
            UIFactory.PlaceTL((RectTransform)weaponSlotButton.transform, rx, 108f, 270f, 64f);
            armorSlotButton = UIFactory.Button("ArmorSlot", win, "", 18, UIFactory.ButtonColor, out armorSlotText);
            UIFactory.PlaceTL((RectTransform)armorSlotButton.transform, rx + 280f, 108f, 270f, 64f);

            inventoryTitleText = UIFactory.Label("InvHeader", win, "INVENTORY", 18, TextAnchor.MiddleLeft, UIFactory.AccentColor, FontStyle.Bold);
            UIFactory.PlaceTL(inventoryTitleText.rectTransform, rx, 186f, 400f, 30f);

            inventorySlotButtons = new Button[InventorySlots];
            inventorySlotTexts = new Text[InventorySlots];
            inventorySlotImages = new Image[InventorySlots];
            for (int i = 0; i < InventorySlots; i++)
            {
                int col = i % 5;
                int row = i / 5;
                var b = UIFactory.Button("Slot_" + i, win, "", 14, UIFactory.ButtonColor, out Text t);
                UIFactory.PlaceTL((RectTransform)b.transform, rx + col * 111f, 220f + row * 70f, 104f, 62f);
                inventorySlotButtons[i] = b;
                inventorySlotTexts[i] = t;
                inventorySlotImages[i] = b.GetComponent<Image>();
            }

            var detail = UIFactory.Panel("ItemDetail", win, new Color(0f, 0f, 0f, 0.35f), false).rectTransform;
            UIFactory.PlaceTL(detail, rx, 508f, 550f, 120f);
            itemDetailText = UIFactory.Label("Text", detail, "", 16, TextAnchor.UpperLeft, Color.white);
            UIFactory.Stretch(itemDetailText.rectTransform, 10f);

            equipButton = UIFactory.Button("Equip", win, "Equip", 20, new Color(0.2f, 0.4f, 0.25f), out _);
            UIFactory.PlaceTL((RectTransform)equipButton.transform, rx, 640f, 270f, 50f);
            salvageButton = UIFactory.Button("Salvage", win, "Salvage", 20, new Color(0.45f, 0.32f, 0.12f), out salvageButtonText);
            UIFactory.PlaceTL((RectTransform)salvageButton.transform, rx + 280f, 640f, 270f, 50f);
        }

        void BuildModals()
        {
            // Pause
            var pause = UIFactory.Modal("PausePanel", transform, new Vector2(440f, 420f), out pausePanel);
            UIFactory.PlaceTL(UIFactory.Label("Title", pause, "PAUSED", 40, TextAnchor.MiddleCenter, UIFactory.AccentColor, FontStyle.Bold).rectTransform, 0f, 24f, 440f, 56f);
            resumeButton = ModalButton(pause, "Resume", 100f);
            saveButton = ModalButton(pause, "Save Game", 170f);
            pauseMenuButton = ModalButton(pause, "Main Menu", 240f);
            pauseQuitButton = ModalButton(pause, "Quit Game", 310f);

            // Defeat
            var defeat = UIFactory.Modal("DefeatPanel", transform, new Vector2(620f, 380f), out defeatPanel, new Color(0.14f, 0.05f, 0.05f, 0.97f));
            UIFactory.PlaceTL(UIFactory.Label("Title", defeat, "YOU HAVE FALLEN", 44, TextAnchor.MiddleCenter, new Color(1f, 0.35f, 0.3f), FontStyle.Bold).rectTransform, 0f, 28f, 620f, 60f);
            defeatInfoText = UIFactory.Label("Info", defeat, "", 20, TextAnchor.MiddleCenter, Color.white);
            UIFactory.PlaceTL(defeatInfoText.rectTransform, 30f, 100f, 560f, 80f);
            retryButton = UIFactory.Button("Retry", defeat, "Retry Floor", 22, new Color(0.45f, 0.18f, 0.15f), out _);
            UIFactory.PlaceTL((RectTransform)retryButton.transform, 60f, 220f, 240f, 60f);
            defeatMenuButton = UIFactory.Button("Menu", defeat, "Main Menu", 22, UIFactory.ButtonColor, out _);
            UIFactory.PlaceTL((RectTransform)defeatMenuButton.transform, 320f, 220f, 240f, 60f);

            // Victory
            var victory = UIFactory.Modal("VictoryPanel", transform, new Vector2(680f, 380f), out victoryPanel, new Color(0.06f, 0.1f, 0.07f, 0.97f));
            victoryTitleText = UIFactory.Label("Title", victory, "FLOOR CLEARED!", 44, TextAnchor.MiddleCenter, UIFactory.AccentColor, FontStyle.Bold);
            UIFactory.PlaceTL(victoryTitleText.rectTransform, 0f, 28f, 680f, 60f);
            victoryInfoText = UIFactory.Label("Info", victory, "", 20, TextAnchor.MiddleCenter, Color.white);
            UIFactory.PlaceTL(victoryInfoText.rectTransform, 30f, 100f, 620f, 80f);
            nextFloorButton = UIFactory.Button("NextFloor", victory, "Next Floor", 22, new Color(0.2f, 0.42f, 0.25f), out _);
            UIFactory.PlaceTL((RectTransform)nextFloorButton.transform, 70f, 220f, 260f, 60f);
            keepExploringButton = UIFactory.Button("Explore", victory, "Keep Exploring", 22, UIFactory.ButtonColor, out _);
            UIFactory.PlaceTL((RectTransform)keepExploringButton.transform, 350f, 220f, 260f, 60f);
        }

        static Button ModalButton(RectTransform parent, string label, float y)
        {
            var b = UIFactory.Button(label.Replace(" ", ""), parent, label, 22, UIFactory.ButtonColor, out _);
            UIFactory.PlaceTL((RectTransform)b.transform, 70f, y, 300f, 56f);
            return b;
        }
    }
}
